import{_ as t,o,c as a,a2 as l}from"./chunks/framework.Crpw6aS5.js";const h=JSON.parse('{"title":"1975年 · 纺织危机与保险困局","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1975年.md","filePath":"05_quotes/by-year/1975年.md"}'),r={name:"05_quotes/by-year/1975年.md"};function u(c,e,q,p,s,_){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_1975年-·-纺织危机与保险困局" tabindex="-1">1975年 · 纺织危机与保险困局 <a class="header-anchor" href="#_1975年-·-纺织危机与保险困局" aria-label="Permalink to &quot;1975年 · 纺织危机与保险困局&quot;">​</a></h1><blockquote><p>去年在谈及1975年的前景时，我们曾表示&quot;1975年的前景不容乐观&quot;。事实证明，这一预测不幸精准应验。——巴菲特（45岁）</p></blockquote><p>本页收录1975年致股东信中的经典语录。这一年是伯克希尔哈撒韦的&quot;至暗时刻&quot;：营业利润671万美元，ROE仅7.6%，创下1967年以来最低纪录。保险业务遭遇行业史上最糟糕的一年，纺织业务陷入极度低迷。但这同时也是黎明前的黑暗。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>去年在谈及1975年的前景时，我们曾表示&quot;1975年的前景不容乐观&quot;。事实证明，这一预测不幸精准应验。</p></blockquote><blockquote><p>但总体而言，当前趋势显示1976年的情况将有所好转。</p></blockquote><blockquote><p>与以往的周期性衰退不同，本轮周期中大多数纺织生产商迅速根据订单量削减产量，从而避免了全行业大规模的库存积压。</p></blockquote><blockquote><p>灾难性的亏损主要集中在汽车保险与长尾业务领域。</p></blockquote><blockquote><p>经济通胀背景下，人身损害与财产修复的成本增速远超整体通胀率，导致最终损失成本飙升，远超在过往成本环境下制定的保费水平。</p></blockquote><blockquote><p>社会通胀则导致责任认定范围持续扩大，远远超出了保费定价时的预期边界——实质上相当于在投保人已支付的保费之外，额外增加了保障责任。</p></blockquote><blockquote><p>我们的权益投资高度集中于少数几家公司，选股标准包括：具备良好的经营特质、管理层能力出众且诚信正直、收购价格相较于私营企业估值标准具备吸引力。</p></blockquote><blockquote><p>只要上述标准持续成立，我们就会长期持有这些股票。事实上，我们规模最大的一笔权益投资，是持有467150股华盛顿邮报B类普通股，持仓成本为1060万美元，我们计划永久持有该笔投资。</p></blockquote><blockquote><p>我们的权益投资高度集中于少数几家公司，选股标准包括：具备良好的经营特质、管理层能力出众且诚信正直、收购价格相较于私营企业估值标准具备吸引力。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1975年是伯克希尔哈撒韦业绩最差的一年。ROE仅7.6%，是1967年以来的最低水平。保险业务遭遇了&quot;史上最糟糕的一年&quot;——经济通胀导致赔付成本飙升，社会通胀导致责任认定不断扩大，大量保险公司破产。纺织业务上半年极度低迷，产量最大降幅达53%。但V型衰退迅速反弹，旺贝克纺织厂在年末扭亏为盈。这是黎明前的黑暗，1976年即将迎来显著反弹。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/1975年/翻译.html">01_letters/1975年/翻译</a> · <a href="/01_letters/1975年/核心总结.html">01_letters/1975年/核心总结</a> · <a href="/01_letters/1975年/思维导图.html">01_letters/1975年/思维导图</a></p>',20)])])}const n=t(r,[["render",u]]);export{h as __pageData,n as default};
